#!/usr/bin/env bash
# Documentation : la clé des catégories.
# Prérequis : apply-fix-categories.sh. Aucune migration.
# Usage (racine du repo) : bash apply-docs-categories.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx" 2>/dev/null | grep -qF "### Une clé pour ce que le code reconnaît"; then echo "Déjà appliqué (commité)."; exit 0; fi
