MODIFIED=("apps/web/content/docs/dev/contenu/un-contenu-fait-de-blocs.mdx" "apps/web/content/docs/dev/domaine/ce-que-voit-le-visiteur.mdx" "apps/web/content/docs/dev/domaine/comprendre-le-domaine.mdx" "apps/web/content/docs/dev/domaine/les-conventions.mdx" "apps/web/content/docs/dev/domaine/un-modele-qui-s-ouvre.mdx" "apps/web/content/docs/dev/etude-de-cas/un-tutoriel-en-donnees.mdx" "apps/web/content/docs/dev/formulaires/le-modele-hybride-face-au-reel.mdx" "apps/web/content/docs/dev/formulaires/les-pieges-du-modele-hybride.mdx" "apps/web/content/docs/dev/formulaires/react-hook-form.mdx" "apps/web/content/docs/dev/formulaires/server-actions.mdx" "apps/web/content/docs/dev/infrastructure/la-sandbox.mdx" "apps/web/content/docs/dev/membres/documents-des-membres.mdx" "apps/web/content/docs/dev/membres/les-groupes.mdx" "apps/web/content/docs/dev/qualite/tester-de-bout-en-bout.mdx" "apps/web/content/docs/dev/qualite/typecheck-et-lint.mdx" "apps/web/content/docs/dev/stockage/un-explorateur-sur-un-sac-de-cles.mdx")
