# apps/web/content/docs/dev/demarrer/avant-de-commencer.mdx : une seule ligne du tableau, remplacée si elle est telle quelle (ta version du fichier diffère de la mienne).
git diff --quiet HEAD -- "apps/web/content/docs/dev/demarrer/avant-de-commencer.mdx" || { echo "❌ modifications non commitées dans apps/web/content/docs/dev/demarrer/avant-de-commencer.mdx (rien n'a été touché)"; restore; exit 1; }
MODIFIED+=("apps/web/content/docs/dev/demarrer/avant-de-commencer.mdx")
python3 - <<'PYEOF'
p="apps/web/content/docs/dev/demarrer/avant-de-commencer.mdx"; s=open(p,encoding="utf-8").read()
old="[\"Catégorie\",\"Category\",\"La plus grosse maille de classement (ex. « Cours ») ; elle range aussi la médiathèque.\"]"; new="[\"Catégorie\",\"Category\",\"La plus grosse maille de classement, choisie dans une liste fixe (cours, stage, évènement) ; elle range aussi la médiathèque.\"]"
n=s.count(old)
if n==1: open(p,"w",encoding="utf-8").write(s.replace(old,new)); print("  avant-de-commencer.mdx : ligne « Catégorie » mise à jour")
elif new in s: print("  avant-de-commencer.mdx : déjà à jour")
else: print("  avant-de-commencer.mdx : ligne « Catégorie » introuvable, laissée telle quelle")
PYEOF
[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm typecheck && pnpm lint"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add -- "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
